"612 :     private void findEigenvalues()
613 :         throws InvalidMatrixException {
614 : 
615 :         // compute splitting points
616 :         List<Integer> splitIndices = computeSplits();
617 : 
618 :         // find realEigenvalues in each block
619 :         realEigenvalues = new double[main.length];
620 :         imagEigenvalues = new double[main.length];
621 :         int begin = 0;
622 :         for (final int end : splitIndices) {
623 :             final int n = end - begin;
624 :             switch (n) {
625 : 
626 :             case 1:
627 :                 // apply dedicated method for dimension 1
628 :                 process1RowBlock(begin);
629 :                 break;
630 : 
631 :             case 2:
632 :                 // apply dedicated method for dimension 2
633 :                 process2RowsBlock(begin);
634 :                 break;
635 : 
636 :             case 3:
637 :                 // apply dedicated method for dimension 3
638 :                 process3RowsBlock(begin);
639 :                 break;
640 : 
641 :             default:
642 : 
643 :                 // choose an initial shift for LDL<sup>T</sup> decomposition
644 :                 final double[] range       = eigenvaluesRange(begin, n);
645 :                 final double oneFourth     = 0.25 * (3 * range[0] + range[1]);
646 :                 final int oneFourthCount   = countEigenValues(oneFourth, begin, n);
647 :                 final double threeFourth   = 0.25 * (range[0] + 3 * range[1]);
648 :                 final int threeFourthCount = countEigenValues(threeFourth, begin, n);
649 :                 final boolean chooseLeft   = (oneFourthCount - 1) >= (n - threeFourthCount);
650 :                 final double lambda        = chooseLeft ? range[0] : range[1];
651 : 
652 :                 tau = (range[1] - range[0]) * MathUtils.EPSILON * n + 2 * minPivot;
653 : 
654 :                 // decompose T-&lambda;I as LDL<sup>T</sup>
655 :                 ldlTDecomposition(lambda, begin, n);
656 : 
657 :                 // apply general dqd/dqds method
658 :                 processGeneralBlock(n);
659 : 
660 :                 // extract realEigenvalues
661 :                 if (chooseLeft) {
662 :                     for (int i = 0; i < n; ++i) {
663 :                         realEigenvalues[begin + i] = lambda + work[4 * i];
664 :                     }
665 :                 } else {
666 :                     for (int i = 0; i < n; ++i) {
667 :                         realEigenvalues[begin + i] = lambda - work[4 * i];
